local uihelper = require(script.Parent.UIHelper)
local bindablefunc: BindableFunction = script.Parent.Parent.BindableFunction
local event = script.Parent:WaitForChild("_windowEvent")

local module = {}
module.__index = module

function module.new(vm, v)
	local self = {}
	local mt = {
		_openCallbacks = nil,
		_closeCallbacks = nil,

		_name = v,
		_belong = vm,
		_showing = false,

		_view = nil,
		_content = nil,

		_getVMS = function(self, vm)
			local vms = bindablefunc:Invoke("_getViewModelScript", vm)
			return vms
		end,
		_getView = function(self)
			if self._view then
				return self._view
			end
			local vms = self:_getVMS(vm)
			if vms then
				if vms:FindFirstChild("View") and vms.View:FindFirstChild(v) then
					self._view = require(vms.View[v])
					return self._view
				end
			end
		end,
		_getContent = function(self)
			if self._content then
				return self._content
			end
			local view = self:_getView()
			if view then
				local content = view:GetContent()
				assert(
					content and typeof(content) == "Instance",
					"[ NezaUI ] View must return a Instance " .. self._name
				)
				self._content = content
				return self._content
			end
		end,

		_getOpenCallbacks = function(self)
			if not self._openCallbacks then
				self._openCallbacks = {}
				local vms = vm and bindablefunc:Invoke("_getViewModelScript", vm)
				if not vms then
					vms = self._view.DataContext and self._view.DataContext._script
				end
				if vms then
					local vm = require(vms)
					if vm["OnShow"] then
						table.insert(self._openCallbacks, function(...)
							vm["OnShow"](vm, ...)
						end)
					end
					if vms:FindFirstChild("View") then
						for i, v in pairs(vms.View:GetDescendants()) do
							if not v:IsA("ModuleScript") then
								continue
							end
							local view = require(v)
							if view["OnShow"] then
								table.insert(self._openCallbacks, function(...)
									view["OnShow"](view, ...)
								end)
							end
						end
					end
				else
					if self._view.OnShow then
						table.insert(self._openCallbacks, function(...)
							self._view.OnShow(self._view, ...)
						end)
					end
				end
			end

			return self._openCallbacks
		end,

		_getCloseCallbacks = function(self)
			if not self._closeCallbacks then
				self._closeCallbacks = {}
				local vms = vm and bindablefunc:Invoke("_getViewModelScript", vm)
				if not vms then
					vms = self._view.DataContext and self._view.DataContext._script
				end
				if vms then
					local vm = require(vms)
					if vm["OnHide"] then
						table.insert(self._closeCallbacks, function(...)
							vm["OnHide"](vm, ...)
						end)
					end
					if vms:FindFirstChild("View") then
						for i, v in pairs(vms.View:GetDescendants()) do
							if not v:IsA("ModuleScript") then
								continue
							end
							local view = require(v)
							if view["OnHide"] then
								table.insert(self._closeCallbacks, function(...)
									view["OnHide"](view, ...)
								end)
							end
						end
					end
				else
					if self._view.OnHide then
						table.insert(self._closeCallbacks, function(...)
							self._view.OnHide(self._view, ...)
						end)
					end
				end
			end

			return self._closeCallbacks
		end,

		_getTransition = function(self, transitionType)
			local view = self:_getView()
			if view then
				if transitionType == "In" then
					return view.ApplyTransitionIn and function(...)
						return view:ApplyTransitionIn(...)
					end
				elseif transitionType == "Out" then
					return view.ApplyTransitionOut and function(...)
						return view:ApplyTransitionOut(...)
					end
				end
			end
		end,
	}

	for i, v in pairs(module) do
		mt[i] = v
	end

	setmetatable(self, {
		__index = function(t, k)
			if mt[k] ~= nil then
				return mt[k]
			end
			local value = rawget(t, k)
			return value
		end,
	})

	return self
end

function module:OnShown(...)
	local args = { ... }
	local _openCallbacks = self:_getOpenCallbacks()
	for i, v in pairs(_openCallbacks) do
		spawn(function()
			local suc, err = pcall(v, table.unpack(args))
			if not suc then
				warn(err)
				warn(debug.traceback())
			end
		end)
	end
	event:Fire("Show", self._name, ...)
end

function module:Show(navigator, ...)
	if self._navigator and self._navigator ~= navigator then
		self._navigator:Pop(self)
	end

	if self._showing then
		return
	end
	local content = self:_getContent()
	if content then
		self._showing = true
		self._navigator = navigator
		local parent = self._navigator:GetContent()

		-- 获取过渡动画
		local transition = self:_getTransition("In")
		local navigatorTransition = self._navigator._getTransition("In")

		local transitionType, tweenInfo, transitionObj
		if navigatorTransition then
			transitionType, tweenInfo, transitionObj =
				navigatorTransition(self._navigator._viewProvider(), self:_getView())
		end
		if transition then
			transitionType, tweenInfo, transitionObj = transition(self._navigator._viewProvider(), self:_getView())
		end

		uihelper:Show(content, parent, transitionType, tweenInfo, transitionObj)
		self:OnShown(...)
		return true
	end
end

function module:OnHidden(...)
	local args = { ... }
	local _closeCallbacks = self:_getCloseCallbacks()
	for i, v in pairs(_closeCallbacks) do
		spawn(function()
			local suc, err = pcall(v, table.unpack(args))
			if not suc then
				warn(err)
				warn(debug.traceback())
			end
		end)
	end
	event:Fire("Hide", self._name, ...)
end

function module:Hide(...)
	if not self._showing then
		return
	end
	local content = self:_getContent()
	if content then
		self._showing = false

		-- 获取过渡动画
		local transition = self:_getTransition("Out")
		local navigatorTransition = self._navigator._getTransition("Out")
		local transitionType, tweenInfo, transitionObj
		if navigatorTransition then
			transitionType, tweenInfo, transitionObj =
				navigatorTransition(self._navigator._viewProvider(), self:_getView())
		end
		if transition then
			transitionType, tweenInfo, transitionObj = transition(self._navigator._viewProvider(), self:_getView())
		end

		uihelper:Hide(content, transitionType, tweenInfo, transitionObj)
		self:OnHidden(...)
	end
end

return module
